let n = 0;
for (const [name, args, expected] of CASES) {
  const got = ex[name](...args);
  // The recorded outputs hold only booleans, strings and null. A key set to undefined would
  // vanish in JSON, so the key sets of the raw object are compared too.
  assert.deepStrictEqual(JSON.parse(JSON.stringify(got)), expected, `${name}(${JSON.stringify(args)})`);
  if (got && typeof got === "object") {
    assert.deepStrictEqual(Object.keys(got).sort(), Object.keys(expected).sort(), `${name} keys (${JSON.stringify(args)})`);
  } else {
    assert.equal(typeof got, typeof expected, `${name} type`);
  }
  n++;
}
assert.equal(n, 1624);
console.log(`entry-rule characterization: ${n} cases unchanged`);
